  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Evidence and Natural Selection$j$, $j${"readings": [{"title": "Job 38 (King James Version)", "url": "/portal/bible/Job/38"}], "body": "Florida requires every biology student to understand the scientific theory of evolution, the idea that populations of living things change over many generations. At New Life Preparatory Academy we study the evidence honestly and carefully, and we hold with joy that God is the Creator of all things. Job 38:4 says, Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding. A good student understands what scientists claim, what evidence supports it, and where faith and science answer different questions.\n\nNatural selection, described by Charles Darwin and Alfred Russel Wallace and published by Darwin in 1859, explains how populations become adapted to their environments. It rests on these observations:\nVariation: individuals in a population differ, and many differences are inherited.\nOverproduction: more offspring are born than can survive.\nCompetition: individuals compete for food, space and mates.\nDifferential survival and reproduction: individuals with helpful traits tend to survive and leave more offspring.\nOver generations, helpful traits become more common. An adaptation is an inherited trait that improves survival or reproduction. Fitness is the ability to survive and reproduce.\n\nEvidence scientists cite:\nFossil record: shows change over time and transitional forms such as Tiktaalik and Archaeopteryx.\nHomologous structures: similar bones with different uses (human arm, whale flipper, bat wing). Analogous structures have similar function but different origin (bird and insect wings). Vestigial structures are reduced features.\nEmbryology: early embryos of vertebrates look alike.\nMolecular biology: similar DNA and proteins in related organisms.\nBiogeography: where species live fits their relationships.\nDirect observation: bacteria becoming resistant to antibiotics; the average beak size of Galapagos finches changing during a drought.\n\nNatural selection acts on existing variation. Mutations create new alleles, but selection does not create the mutations and does not plan. Types of selection: directional, stabilizing and disruptive.\n\nYour task: (1) List the four parts of natural selection. (2) Explain how antibiotic resistance shows natural selection. (3) Give one example of a homologous structure and tell what it suggests.\n\nFlorida standards: SC.912.L.15.1, SC.912.L.15.13.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.15.1, SC.912.L.15.13", "script": "Welcome to Unit 5. This is Dr. Jenkins. Listen, Florida requires every biology student to understand the scientific theory of evolution, and at New Life Preparatory Academy we study the evidence honestly and carefully, while we hold with joy that God is the Creator of all things. Job thirty eight and four says, Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding. A wise student understands what scientists claim, what evidence supports it, and where faith and science answer different questions.\n\nNow watch this. Natural selection was described by Charles Darwin and Alfred Russel Wallace, and Darwin published it in eighteen fifty nine. It rests on four observations. Variation, individuals differ and many differences are inherited. Overproduction, more offspring are born than can survive. Competition, they compete for food, space and mates. And differential survival, those with helpful traits tend to survive and leave more offspring. Over generations, helpful traits become more common. An adaptation is an inherited trait that improves survival or reproduction. Fitness is the ability to survive and reproduce.\n\nLook at the evidence scientists cite. The fossil record, with transitional forms like Tiktaalik and Archaeopteryx. Homologous structures, similar bones with different uses, like a human arm, a whale flipper and a bat wing. Analogous structures have the same function but different origin, like bird and insect wings. Vestigial structures are reduced features. Embryology, since vertebrate embryos look alike early on. Molecular biology, since related organisms have similar DNA and proteins. Biogeography, since where species live fits their relationships. And direct observation, like bacteria becoming resistant to antibiotics, and the beak size of Galapagos finches changing during a drought.\n\nSelection acts on variation that already exists. Mutations create new alleles, but selection does not create them and does not plan ahead. The types of selection are directional, stabilizing and disruptive.\n\nYour task today. List the four parts of natural selection. Explain how antibiotic resistance shows natural selection. And give an example of a homologous structure. Take the four question check when you finish.\n\nHonest study honors the Creator and sharpens the mind. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Evidence and Natural Selection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Classification of Living Things$j$, $j${"readings": [{"title": "Romans 1 (King James Version)", "url": "/portal/bible/Romans/1"}], "body": "There are millions of kinds of living things, so scientists classify them into groups. Romans 1:20 says, For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse. The orderly variety of life invites careful study.\n\nTaxonomy is the science of naming and classifying organisms. Carolus Linnaeus began the system we use. Each organism has a two part scientific name, binomial nomenclature, made of the genus (capitalized) and the species (lowercase), written in italics or underlined. Example: Homo sapiens (humans), Canis lupus (wolf).\n\nLevels from largest to smallest: Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species. A memory aid: Dear King Philip Came Over For Good Soup. Organisms in the same genus are closely related.\n\nThree domains:\nBacteria: prokaryotes, true bacteria.\nArchaea: prokaryotes, often in extreme places like hot springs.\nEukarya: eukaryotes, including the kingdoms Protista, Fungi, Plantae and Animalia.\n\nFeatures used: cell type (prokaryote or eukaryote), number of cells, how it gets food (autotroph or heterotroph), cell wall, and reproduction. Modern classification also uses DNA and protein comparisons to show evolutionary relationships.\n\nA cladogram is a branching diagram that shows relationships. Each branch point shows where groups share a common ancestor, and shared derived characteristics (traits that arose in a common ancestor) group the organisms. Groups closer together on the diagram are more closely related.\n\nA dichotomous key is a tool to identify an organism by answering a series of either or questions.\n\nYour task: (1) Write the scientific name of a human and explain the two parts. (2) List the eight levels of classification in order. (3) Use a cladogram to explain what it means when two species share a recent common ancestor.\n\nFlorida standards: SC.912.L.15.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.15.6", "script": "Welcome back. Dr. Jenkins here. Listen, there are millions of kinds of living things, so scientists organize them into groups. Romans one and twenty says, For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse. The orderly variety of life invites careful study.\n\nTaxonomy is the science of naming and classifying organisms, and Carolus Linnaeus began the system we use. Every organism has a two part scientific name called binomial nomenclature. The genus is capitalized, the species is lowercase, and both are written in italics or underlined. Homo sapiens is a human. Canis lupus is a wolf.\n\nNow watch this. The levels from largest to smallest are domain, kingdom, phylum, class, order, family, genus and species. A memory aid is, Dear King Philip Came Over For Good Soup. Organisms in the same genus are closely related.\n\nThere are three domains. Bacteria are prokaryotes, the true bacteria. Archaea are also prokaryotes, often living in extreme places like hot springs. And Eukarya includes all eukaryotes, with the kingdoms Protista, Fungi, Plantae and Animalia. Scientists look at cell type, the number of cells, how the organism gets food, whether it has a cell wall, and how it reproduces. Today they also compare DNA and proteins to show evolutionary relationships.\n\nLook at a cladogram. It is a branching diagram. Each branch point shows a common ancestor, and shared derived characteristics, traits that arose in a common ancestor, group the organisms. Groups closer together are more closely related. And a dichotomous key identifies an organism by answering a series of either or questions.\n\nYour task today. Write the scientific name of a human and explain the two parts. List the eight levels in order. And use a cladogram to explain what a recent common ancestor means. Take the four question check when you finish.\n\nGod is not the author of confusion, and creation is full of order. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Classification of Living Things$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 The Origin of Life: Scientific Explanations$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Where did life come from? Genesis 1:1 says, In the beginning God created the heaven and the earth. Christians believe God is the Author of life. Science asks a different question: what natural processes can be studied and tested? Florida standards require students to describe scientific explanations of the origin of life on earth, and an informed believer can understand them, weigh their strengths and limits, and still confess God as Creator.\n\nSpontaneous generation was the old idea that life arises from nonliving matter every day, such as maggots from meat. Francesco Redi (1668) covered jars of meat with cloth and no maggots appeared. Louis Pasteur (1860s) used swan neck flasks to show that microbes come from existing microbes. So today life comes from life, which supports cell theory.\n\nScientific hypotheses about early life on earth:\nEarth is about 4.5 billion years old, according to radiometric dating. The oldest fossils of cells are about 3.5 billion years old.\nOparin and Haldane proposed that early earth had simple molecules that formed more complex molecules.\nMiller and Urey (1953) put water, methane, ammonia and hydrogen in a flask with sparks and made amino acids. This showed that building blocks can form from simple chemicals under such conditions. It did not produce life.\nThe RNA world hypothesis suggests that RNA, which can store information and speed up some reactions, came before DNA and proteins.\nMembrane bubbles (protocells) may have enclosed molecules.\nThe first cells were probably prokaryotes. Photosynthetic bacteria later added oxygen to the air. Eukaryotic cells may have formed when one cell lived inside another (endosymbiotic theory).\n\nLimits: Scientists have not shown how a living cell first formed, and these explanations are still being researched. They are hypotheses, not settled facts. Science cannot test questions about ultimate purpose or whether God acted, and a believer looks at the evidence with reverence. Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding.\n\nYour task: (1) Explain what Redi and Pasteur showed. (2) Tell what the Miller and Urey experiment did and did not show. (3) In a short paragraph, explain how a Christian student can study the scientific explanations while holding to Genesis 1:1.\n\nFlorida standards: SC.912.L.15.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.15.8", "script": "Welcome back. Dr. Jenkins here. Listen, where did life come from? Genesis one and one says, In the beginning God created the heaven and the earth. We believe God is the Author of life. Science asks a different question: what natural processes can be studied and tested? Florida requires students to describe the scientific explanations of the origin of life, and an informed believer can understand them, weigh their strengths and limits, and still confess God as Creator.\n\nLet us start with an old idea, spontaneous generation, that life arises from nonliving matter every day, like maggots from meat. Francesco Redi, in sixteen sixty eight, covered jars of meat with cloth and no maggots appeared. Louis Pasteur, in the eighteen sixties, used swan neck flasks to show that microbes come from existing microbes. So today life comes from life, which supports cell theory.\n\nNow watch this. Scientists estimate that earth is about four and a half billion years old, and the oldest fossils of cells are about three and a half billion years old. Oparin and Haldane proposed that early earth had simple molecules that formed more complex ones. Miller and Urey, in nineteen fifty three, put water, methane, ammonia and hydrogen in a flask with sparks and made amino acids. That showed building blocks can form from simple chemicals under such conditions. It did not make life. The RNA world hypothesis suggests RNA, which can store information and speed up some reactions, came before DNA and proteins. Membrane bubbles called protocells may have enclosed molecules. The first cells were probably prokaryotes, photosynthetic bacteria added oxygen to the air, and eukaryotic cells may have formed when one cell lived inside another.\n\nBe honest about the limits. Scientists have not shown how a living cell first formed. These are hypotheses still being researched, not settled facts. Science cannot test questions about ultimate purpose, or whether God acted, and a believer looks at the evidence with reverence. Proverbs three and five says, Trust in the LORD with all thine heart; and lean not unto thine own understanding.\n\nYour task today. Explain what Redi and Pasteur showed. Tell what Miller and Urey did and did not show. And write a short paragraph on how a Christian student can study the science while holding to Genesis one and one. Take the four question check when you finish.\n\nWe study with understanding and worship with all our heart. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 The Origin of Life: Scientific Explanations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Populations, Speciation and Extinction$j$, $j${"readings": [{"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}], "body": "A population is a group of the same species living in one area. Evolution is studied by watching how the alleles in a population change. Genetic variation in a population comes from mutation, sexual reproduction (meiosis and fertilization) and gene flow. First Thessalonians 5:21 says, Prove all things; hold fast that which is good. A good scientist tests claims and keeps what holds up.\n\nGene pool: all the alleles in a population. Allele frequency is how common an allele is. Evolution at its smallest scale is a change in allele frequency over time.\n\nWays a population changes:\nNatural selection: helpful alleles become more common.\nGenetic drift: chance changes in allele frequency, strongest in small populations, such as after a disaster (bottleneck effect) or when a small group starts a new population (founder effect).\nGene flow: movement of alleles when individuals migrate and breed.\nMutation: adds new alleles.\nNon random mating: choosing mates by certain traits.\n\nSpeciation is the formation of new species. A species is a group that can interbreed and produce fertile offspring. Populations that are separated (geographic isolation, such as a mountain or river) can change in different ways. If they can no longer interbreed, they are separate species (reproductive isolation). Adaptive radiation is the rapid formation of many species from one ancestor, as with the Galapagos finches.\n\nExtinction is the disappearance of a species. Causes include habitat loss, climate change, competition, disease and overhunting. Today human activity is a major cause. Variation is important because a population with more variation is more likely to survive a change.\n\nEvolution is also seen in patterns: Convergent evolution gives similar traits in unrelated species in similar environments (sharks and dolphins). Divergent evolution gives different traits from a common ancestor. Coevolution is two species changing in response to each other (flowers and bees).\n\nYour task: (1) Define gene pool and allele frequency. (2) Explain how geographic isolation can lead to a new species. (3) Tell why a small population is more at risk of losing variation.\n\nFlorida standards: SC.912.L.15.13.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.15.13", "script": "Welcome back. Dr. Jenkins here. Listen, First Thessalonians five and twenty one says, Prove all things; hold fast that which is good. A good scientist tests claims and keeps what holds up. Today we look at how populations change.\n\nA population is a group of the same species living in one area. Variation in a population comes from mutation, from sexual reproduction, through meiosis and fertilization, and from gene flow. The gene pool is all the alleles in a population. Allele frequency is how common an allele is. At its smallest scale, evolution is a change in allele frequency over time.\n\nNow watch this. How does a population change? Natural selection makes helpful alleles more common. Genetic drift is chance change in allele frequency, strongest in small populations, like after a disaster, called the bottleneck effect, or when a small group starts a new population, called the founder effect. Gene flow is the movement of alleles when individuals migrate and breed. Mutation adds new alleles. And non random mating means choosing mates by certain traits.\n\nLook at speciation. A species is a group that can interbreed and produce fertile offspring. When populations are separated, by a mountain or a river for example, they can change in different ways. If they can no longer interbreed, they are separate species. Adaptive radiation is the rapid formation of many species from one ancestor, like the Galapagos finches.\n\nExtinction is the disappearance of a species. Causes include habitat loss, climate change, competition, disease and overhunting. Today human activity is a major cause. A population with more variation is more likely to survive a change.\n\nThree patterns. Convergent evolution gives similar traits in unrelated species in similar environments, like sharks and dolphins. Divergent evolution gives different traits from a common ancestor. And coevolution is two species changing in response to each other, like flowers and bees.\n\nYour task today. Define gene pool and allele frequency. Explain how geographic isolation can lead to a new species. And tell why a small population is more at risk of losing variation. Take the four question check when you finish.\n\nTest everything and hold fast what is good. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Populations, Speciation and Extinction$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Classification Key and Evidence Report$j$, $j${"prompt": "Part 1: Dichotomous Key. Make a dichotomous key with at least five steps that identifies six living things (for example, oak tree, fern, earthworm, grasshopper, frog and bird). Use clear either or statements.\n\nPart 2: Classification. Write the full classification (domain to species) of a human, and explain what the first word and second word of a scientific name mean. Romans 1:20 says, For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse.\n\nPart 3: Evidence Report. Choose three kinds of evidence scientists use in the study of evolution (fossils, homologous structures, DNA, embryology, biogeography or direct observation). For each, give an example and explain what it suggests. In one paragraph tell one limit or open question in the science.\n\nPart 4: Natural Selection Case. Describe a case (such as peppered moths, finch beaks or antibiotic resistance). Use the four parts of natural selection to explain how a trait became more common in the population.\n\nPart 5: Origin of Life. In at least 100 words, summarize the experiments of Redi, Pasteur and Miller and Urey and explain how a Christian student can study the science while confessing Genesis 1:1.", "rubric": "70 points. Dichotomous key: 12 points. Classification and naming: 10 points. Evidence report: 18 points. Natural selection case: 14 points. Origin of life summary: 12 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Classification Key and Evidence Report$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Studying Creation with Understanding$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words how natural selection can change a population over generations, (2) describes one piece of evidence that scientists use to study the history of life and what you think it shows, (3) tells how a Christian can study science honestly, with integrity and humility, while trusting that God is the Creator of all things, and (4) connects your answer to Job 38:4, which says, Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding. Then write a respectful reply of at least 40 words to another student, or answer this question: Why is it important to tell the difference between what science can test and what faith confesses? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Studying Creation with Understanding$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Evidence and Natural Selection$j$, $j${"questions": [{"q": "Which is a requirement for natural selection to occur?", "options": ["Inherited variation among individuals", "No competition", "No offspring", "All individuals identical"]}, {"q": "The bones in a human arm, a whale flipper and a bat wing are examples of:", "options": ["Fossils", "Homologous structures", "Analogous structures", "Mutations"]}, {"q": "An adaptation is best described as:", "options": ["A change an animal makes by wanting to", "An inherited trait that improves survival or reproduction", "A trait that was learned", "A mutation that always kills"]}, {"q": "The spread of antibiotic resistance in bacteria is an example of:", "options": ["Cloning", "Osmosis", "Natural selection observed directly", "Photosynthesis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Evidence and Natural Selection$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,2}'::int[], array[$j$Variation that can be inherited is needed for selection to act.$j$,$j$Similar bone patterns with different uses are homologous structures.$j$,$j$Adaptations are inherited traits that increase fitness.$j$,$j$Resistant bacteria survive treatment and pass the trait on.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Evidence and Natural Selection$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Classification of Living Things$j$, $j${"questions": [{"q": "In the name Homo sapiens, the word Homo is the:", "options": ["Species", "Family", "Genus", "Kingdom"]}, {"q": "Which is the largest classification group?", "options": ["Kingdom", "Species", "Phylum", "Domain"]}, {"q": "Prokaryotic organisms are placed in which two domains?", "options": ["Archaea and Eukarya", "Bacteria and Archaea", "Eukarya and Bacteria", "Plantae and Animalia"]}, {"q": "On a cladogram, two groups that branch from a recent common ancestor are:", "options": ["More closely related", "The same species", "Always extinct", "Not related"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Classification of Living Things$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,0}'::int[], array[$j$The first word of a scientific name is the genus.$j$,$j$Domain is the broadest level.$j$,$j$Bacteria and Archaea are the two prokaryote domains.$j$,$j$A more recent shared ancestor means closer relationship.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Classification of Living Things$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: The Origin of Life: Scientific Explanations$j$, $j${"questions": [{"q": "Pasteur's swan neck flask experiment helped show that:", "options": ["Oxygen makes life", "Microbes come from existing microbes", "Life appears from broth every day", "Bacteria are not alive"]}, {"q": "The Miller and Urey experiment produced:", "options": ["Amino acids from simple chemicals", "DNA only", "A living cell", "A new species"]}, {"q": "The RNA world hypothesis suggests that:", "options": ["DNA is the oldest molecule", "RNA may have come before DNA and proteins", "Proteins made RNA first", "Lipids are the only biomolecule"]}, {"q": "Redi's experiment with jars of meat tested the idea of:", "options": ["Natural selection", "Spontaneous generation", "Cell division", "Photosynthesis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: The Origin of Life: Scientific Explanations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,1}'::int[], array[$j$It disproved spontaneous generation of microbes.$j$,$j$It showed building blocks of life can form, but it did not make life.$j$,$j$RNA can store information and speed up some reactions.$j$,$j$Covered jars stayed free of maggots, challenging spontaneous generation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: The Origin of Life: Scientific Explanations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Populations, Speciation and Extinction$j$, $j${"questions": [{"q": "All the alleles in a population make up its:", "options": ["Genus", "Gene pool", "Cladogram", "Habitat"]}, {"q": "Chance changes in allele frequency in a small population are called:", "options": ["Mitosis", "Genetic drift", "Gene flow", "Natural selection"]}, {"q": "Two populations separated by a river that can no longer interbreed show:", "options": ["Photosynthesis", "Reproductive isolation leading to speciation", "Mitosis", "A food web"]}, {"q": "Sharks and dolphins have similar body shapes because of:", "options": ["Gene flow", "Recent common ancestry", "Convergent evolution", "Cloning"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Populations, Speciation and Extinction$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,2}'::int[], array[$j$The gene pool is the total set of alleles in a population.$j$,$j$Genetic drift is random change and is strongest in small populations.$j$,$j$Isolation can lead to the formation of separate species.$j$,$j$Similar environments led to similar traits in unrelated groups.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Populations, Speciation and Extinction$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Evolution, Classification and the Origin of Life$j$, $j${"questions": [{"q": "Which of these must be present for natural selection?", "options": ["No environment", "Identical individuals", "No offspring", "Variation, inheritance and differential survival"]}, {"q": "Which is the best example of an observed case of natural selection?", "options": ["A student learning to swim", "Bacteria becoming resistant to an antibiotic", "A plant growing toward light", "A river changing course"]}, {"q": "Wings of a bird and an insect are:", "options": ["Fossils", "Analogous structures", "Homologous structures", "Vestigial structures"]}, {"q": "The scientific name Canis lupus tells us the organism's:", "options": ["Genus and species", "Class and order", "Family and domain", "Kingdom and phylum"]}, {"q": "Which domain contains organisms that are prokaryotes living in extreme places such as hot springs?", "options": ["Fungi", "Plantae", "Archaea", "Eukarya"]}, {"q": "Redi and Pasteur both showed that:", "options": ["Maggots come from meat", "Life appears from dust", "Life today comes from existing life", "Microbes are not alive"]}, {"q": "The Miller and Urey experiment is important because it showed that:", "options": ["DNA formed on its own", "Amino acids can form from simple chemicals under certain conditions", "A cell can be built in a flask", "God cannot be Creator"]}, {"q": "A small group of birds starts a new island population, and its allele frequencies differ from the original. This is the:", "options": ["Founder effect", "Convergent evolution", "Gene flow", "Bottleneck effect only"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Evolution, Classification and the Origin of Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,0,2,2,1,0}'::int[], array[$j$These conditions let helpful traits increase in the population.$j$,$j$Resistance is inherited and the resistant bacteria survive.$j$,$j$They have a similar function but a different origin.$j$,$j$A binomial name gives genus then species.$j$,$j$Archaea are prokaryotes that often live in extreme environments.$j$,$j$Their experiments challenged spontaneous generation.$j$,$j$It showed building blocks can form, but it did not make life or answer ultimate questions.$j$,$j$A small founding group carries only part of the original gene pool.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Evolution, Classification and the Origin of Life$j$ on conflict (item_id) do nothing;
